{
  "action": "tool",
  "tool": "retrieve_history",
  "args": {
    "research_concepts": ["teammate drive", "pick-and-roll", "points per possession", "play-type sequence", "possession outcome"],
    "methodological_questions": ["causal identification of preceding events", "confounding by game state and player quality", "temporal ordering of play-type labels", "defining PPP for a non-initial action", "overlapping possession events"],
    "query": "teammate DRIVE preceding PNR effect on PNR PPP"
  }
}

{
  "action": "final",
  "output": {
    "research_concepts": [
      "teammate drive",
      "pick-and-roll",
      "points per possession",
      "play-type sequence",
      "possession outcome"
    ],
    "methodological_questions": [
      "causal identification of preceding events",
      "confounding by game state and player quality",
      "temporal ordering of play-type labels within a possession",
      "defining PPP for a possession that contains multiple play-type actions",
      "overlapping possession events and double-counting",
      "sample size for sequences with both a drive and a pick-and-roll"
    ],
    "historical_evidence": [
      {
        "id": "FAM:SF40",
        "status_as_recorded": "not a hypothesis test",
        "finding": "Teammate DRIVE->PNR premium observed (+0.326 PPP for Brown->Tatum, n=43), but later shown to be a placebo artifact (APPS-070). Same-player DRIVE->PNR also observed (+0.309, Doncic). Sequencing premiums exist but are small-sample and lack multiplicity correction."
      },
      {
        "id": "FAM:SF07",
        "status_as_recorded": "supported",
        "finding": "Sequential pair premiums exist: after opponent runs a play type, next offensive play type scores above its unconditional baseline; universal defensive aftershock. Demonstrates that play-type sequencing can affect PPP."
      }
    ],
    "failed_approaches": [
      {
        "id": "FAM:SF40",
        "what_failed": "Brown->Tatum DRIVE->PNR +0.326 (n=43) flagged as placebo artifact in APPS-070",
        "why": "Apparent teammate sequential premium disappeared under placebo testing; indicates vulnerability to false discoveries in sequence-based PPP analyses."
      },
      {
        "id": "FAM:SF-PAP-096",
        "what_failed": "SPOT_UP 2.83 PPP (100% makes) due to assisted-flag leak in play-type classifier",
        "why": "Construction artifact: assisted flag only present on made shots inflated SPOT_UP PPP, demonstrating that labeling flaws can produce large spurious effects."
      }
    ],
    "evidence_establishes": [
      "Teammate DRIVE immediately preceding a PNR has been observed to associate with higher PNR PPP in some specific cases.",
      "General sequential pair premiums exist in NBA play-by-play data, making the question theoretically plausible.",
      "Artifact risks (placebo dependence, classifier leakage) are known and have invalidated similar findings before."
    ],
    "evidence_does_not_establish": [
      "Whether any observed DRIVE->PNR premium is causal or purely associative.",
      "Generalizability beyond a few star pairings.",
      "Robustness to confounding by game state, player quality, or defensive pressure.",
      "That the effect would survive placebo or falsification tests."
    ],
    "own_inferences": [
      "The research question is testable with the available data by defining ‘teammate DRIVE preceding a PNR’ as a same-possession event where a teammate’s DRIVE initiation occurs immediately before the PNR initiation within that possession.",
      "The necessary data elements (initiator, play type, possession points) exist in the graph database and can be filtered appropriately.",
      "Adequate sample sizes across four seasons and playoffs are likely, but power must be formally assessed, especially for stringent controls."
    ],
    "uncertainties": [
      "Exact temporal ordering of play-type labels within a single possession and whether the classifier reliably distinguishes drive-then-PNR from independent actions.",
      "Degree of overlap with other sequencing studies and the risk of overfitting to a few high-leverage players.",
      "Whether the effect size, if real, is large enough to be practically useful beyond statistical detection."
    ],
    "historical_effect": {
      "changed_decision": "yes",
      "explanation": "The retrieval showed that a previously observed teammate DRIVE->PNR premium was later identified as a placebo artifact. Without that evidence, a naive observational test might have reported a positive finding; with it, the design must include rigorous placebo and falsification checks to avoid repeating the same mistake."
    },
    "testability": {
      "p_testable": 0.7,
      "blocking_constraints": [
        {
          "code": "SAMPLE_SIZE_POWER",
          "text": "The number of possessions containing both a teammate DRIVE and a subsequent PNR may be limited; power to detect a small effect (<0.03 PPP) with confound controls could be inadequate without pooling across many seasons."
        },
        {
          "code": "CONFOUNDING",
          "text": "DRIVE occurrence correlates with offensive talent and defensive breakdowns; failing to adjust for initiator quality and game state could produce a spurious positive association."
        },
        {
          "code": "LABEL_ERROR",
          "text": "Play-type classification errors could misattribute DRIVE or PNR events, creating artificial sequence relationships, as seen in SF-PAP-096."
        }
      ]
    },
    "prior_work": {
      "already_answered": "partly",
      "cited": [
        "FAM:SF40",
        "FAM:SF07"
      ],
      "summary": "SF40 explored DRIVE->PNR teammate premiums descriptively but found one prominent example to be a placebo artifact. SF07 established that play-type sequencing can matter for PPP, confirming plausibility. Neither study tested the specific hypothesis ‘any teammate DRIVE preceding a PNR raises PNR PPP’ in a controlled, preregistered manner."
    },
    "risks": [
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "Possessions with both a teammate DRIVE and a PNR may be rare, reducing power and favoring noisy, overfit estimates."
      },
      {
        "code": "CONFOUNDING",
        "text": "Skill correlation between DRIVE initiators and PNR initiators, score effects, and defensive quality can all drive spurious PPP differences."
      },
      {
        "code": "LABEL_ERROR",
        "text": "Classifier mislabeling of drives or PNRs can manufacture sequence patterns that do not reflect genuine basketball events."
      },
      {
        "code": "PLACEBO_DEPENDENCE",
        "text": "Placebo tests (e.g., randomizing the preceding action or using opponent drives) are essential because earlier teammate DRIVE->PNR premium was a placebo artifact."
      },
      {
        "code": "MULTIPLE_TESTING",
        "text": "If multiple play-type pairs are tested without adjustment, false positives are likely; pre-registration must limit the primary test to the DRIVE->PNR pair."
      }
    ],
    "predicted_outcome": {
      "supported": 0.2,
      "rejected": 0.15,
      "untestable": 0.05,
      "artifact": 0.4,
      "uncertain": 0.2
    },
    "decision": "proceed_with_changes",
    "design": {
      "estimand": "Difference in points per possession (PPP) on possessions where a pick-and-roll (PNR) action occurs, comparing those where the same team's preceding action within that possession was a teammate DRIVE (not by the PNR ball-handler) versus those with no preceding teammate DRIVE, adjusted for game context and player quality.",
      "unit": "A single possession that is labelled as containing a PNR action and where a preceding play type within the same possession can be identified.",
      "sample": "All complete regular-season and playoff possessions from 2022-23 through 2025-26 (2025-26 regular season fully available as of 2026-04-13, playoffs partial but use regular season for primary analysis). Exclude possessions with ambiguous temporal ordering or missing data.",
      "power": "Perform a power analysis on a pilot sample (2022-23 through 2024-25). Target at least 1000 treated possessions (DRIVE→PNR) and 5000 control possessions (PNR without preceding teammate DRIVE) to detect an effect size of 0.03 PPP with 80% power at α=0.05, assuming residual standard deviation ~1.2 PPP. If pilot shows fewer than 800 treated possessions after quality filters, adjust to a pooled over-time analysis or widen confidence interval interpretation.",
      "controls": "Fixed effects for season, team (offensive), game location (home/away), quarter, score differential (binned), time remaining (binned), and opponent defensive rating. Adjust for PNR ball-handler and screener identity via a player-quality index (career PNR PPP or rolling average). Include a control for the presence of any preceding teammate action (to separate DRIVE specifically from general preceding action).",
      "falsification": "Primary falsification test: replace the actual preceding action with a randomly chosen teammate action from a different possession (placebo test) and re-estimate the effect; a genuine effect should disappear. Additional placebo: test the effect of preceding opponent DRIVE on own-team PNR PPP (should be zero or negative). Sensitivity analysis: examine subsets defined by whether the DRIVE action drew a defensive rotation (using defender proximity data if available) to test for mechanism.",
      "multiplicity": "Pre-register a single confirmatory test: H0: β_DRIVE→PNR = 0 vs H1: β_DRIVE→PNR > 0. All other sequence pairs are exploratory and will be reported with Benjamini-Hochberg adjusted p-values.",
      "decision_rule": "Supported if the primary test has one-sided p<0.025, the point estimate is >0.02 PPP, the placebo test has p>0.10, and the effect survives inclusion of all pre-specified confounders. If the placebo test is significant, conclude artifact. If the treated sample size after quality cuts is below the pre-registered minimum (e.g., 800), declare untestable due to power.",
      "data_version": "Play-type possession records from the graph database as of 2026-06-14, using the corrected classifier that no longer leaks assisted flags (post SF-PAP-096 fix). Apply the same possession-linkage logic used in SF40 but ensure no lookahead: only actions strictly preceding the PNR within the same possession are eligible."
    }
  }
}

